# 1. Pool 并行计算 + imap_unordered 惰性迭代
import os
import time
from multiprocessing import Pool

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def count_primes_in_range(args):
    start, end = args
    return sum(1 for n in range(start, end) if is_prime(n))

if __name__ == "__main__":
    # 切分任务为 8 块，减少 IPC 次数
    chunk_size = 125
    ranges = [(i, min(i + chunk_size, 101000)) for i in range(100000, 101000, chunk_size)]
    start_time = time.perf_counter()
    with Pool(os.cpu_count()) as pool:
        # imap_unordered: 谁先完成谁先返回，不保序
        total = sum(pool.imap_unordered(count_primes_in_range, ranges))
    elapsed = time.perf_counter() - start_time
    print(f"多进程: {total} 个素数, 耗时 {elapsed:.3f}s")

# 2. Queue 生产者-消费者 IPC
from multiprocessing import Process, Queue

def producer(q, n):
    for i in range(n):
        q.put(i * i)
    q.put(None)  # 哨兵值，通知消费者结束

def consumer(q):
    while True:
        item = q.get()
        if item is None:
            break
        # 处理 item
    print("消费者完成")

if __name__ == "__main__":
    q = Queue(maxsize=100)  # 有界队列，防止生产者过快
    p1 = Process(target=producer, args=(q, 1000))
    p2 = Process(target=consumer, args=(q,))
    p1.start()
    p2.start()
    p1.join()
    p2.join()

# 3. Value 共享内存 + Lock（counter.value += 1 不是原子的）
from multiprocessing import Process, Value, Lock

def increment(counter, lock, n):
    for _ in range(n):
        with lock:
            counter.value += 1

if __name__ == "__main__":
    counter = Value('i', 0)
    lock = Lock()
    processes = [Process(target=increment, args=(counter, lock, 100000)) for _ in range(4)]
    for p in processes:
        p.start()
    for p in processes:
        p.join()
    print(f"Counter: {counter.value}")  # 应为 400000

# 4. ProcessPoolExecutor（更现代的 API）
from concurrent.futures import ProcessPoolExecutor, as_completed

if __name__ == "__main__":
    with ProcessPoolExecutor(max_workers=os.cpu_count()) as executor:
        futures = {executor.submit(count_primes_in_range, r): r for r in ranges}
        total = 0
        for future in as_completed(futures):
            total += future.result()  # 异常在这里抛出
        print(f"ProcessPoolExecutor: {total} 个素数")
